function validate([conversions]) {
  const n = conversions.length + 1;
  if (n < 2 || n > 100000) return 'conversions needs 1 to 99999 entries.';
  const children = Array.from({ length: n }, () => []);
  for (const conversion of conversions) {
    if (conversion.length !== 3) return 'Each conversion is [sourceUnit, targetUnit, conversionFactor].';
    const [source, target, factor] = conversion;
    if (source < 0 || source >= n || target < 0 || target >= n) return 'Units are numbered 0 to n - 1, where n = conversions.length + 1.';
    if (factor < 1 || factor > 1000000000) return 'Each conversionFactor is between 1 and 10^9.';
    children[source].push(target);
  }
  // Following conversions forward from unit 0 must reach every unit exactly once.
  const reached = new Array(n).fill(false);
  reached[0] = true;
  const queue = [0];
  for (let k = 0; k < queue.length; k++) {
    for (const next of children[queue[k]]) {
      if (reached[next]) return 'Each unit must be reachable from unit 0 in exactly one way.';
      reached[next] = true;
      queue.push(next);
    }
  }
  if (queue.length !== n) return 'Every unit must be reachable from unit 0 by forward conversions.';
  return null;
}

