  const amount = new Array(n).fill(0n);
  amount[0] = 1n;
  const queue = [0];
  for (let head = 0; head < queue.length; head++) {
    const unit = queue[head];
    for (const [next, factor] of children[unit]) {
      amount[next] = (amount[unit] * factor) % MOD;
      queue.push(next);
    }
  }
  return amount.map(Number);
}

