function baseUnitConversions(conversions) {
  // Every unit except 0 is the target of exactly one conversion: remember where it comes from.
  const n = conversions.length + 1;
  const parent = new Array(n).fill(-1), factorIn = new Array(n).fill(1n);
  for (const [source, target, factor] of conversions) { parent[target] = source; factorIn[target] = BigInt(factor); }
  // Climb from each unit back to unit 0, multiplying the exact factors, and reduce only at the end.
  const result = [];
  for (let unit = 0; unit < n; unit++) {
    let product = 1n;
    for (let u = unit; u !== 0; u = parent[u]) product *= factorIn[u];
    result.push(Number(product % 1000000007n));
  }
  return result;
}

